package com.bettertoppi.topuhud.modmenu;

import com.bettertoppi.topuhud.config.ConfigManager;import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.client.gui.widget.TextFieldWidget;import net.minecraft.text.Text;import java.util.ArrayList;import java.util.List;
public final class TopuHudScreen extends Screen{private final Screen parent;private TextFieldWidget search;private TopuUtilityManager.Category category;private int scroll;public TopuHudScreen(Screen p){super(Text.literal("TopuHUD ClickGUI"));parent=p;}@Override protected void init(){build();}private void build(){clearChildren();int s=190;search=new TextFieldWidget(textRenderer,s+22,20,width-s-44,28,Text.literal("Search"));search.setMaxLength(40);search.setPlaceholder(Text.literal("Search utilities..."));search.setChangedListener(v->{scroll=0;rebuild();});addDrawableChild(search);nav("ALL",null,18,82);int y=112;for(TopuUtilityManager.Category c:TopuUtilityManager.Category.values()){nav(pretty(c.name()),c,18,y);y+=34;}addDrawableChild(ButtonWidget.builder(Text.literal("HUD EDITOR"),b->openHudEditor()).dimensions(18,height-92,152,24).build());action("ENABLE ALL",18,height-62,true);action("DISABLE ALL",18,height-32,false);rebuild();}private void openHudEditor(){MinecraftClient client=MinecraftClient.getInstance();ConfigManager.save();client.execute(()->client.setScreen(new TopuScreenEditor(this)));}private void nav(String n,TopuUtilityManager.Category c,int x,int y){addDrawableChild(ButtonWidget.builder(Text.literal(n),b->{category=c;scroll=0;rebuild();}).dimensions(x,y,152,27).build());}private void action(String n,int x,int y,boolean v){addDrawableChild(ButtonWidget.builder(Text.literal(n),b->{for(TopuUtilityManager.Utility u:TopuUtilityManager.ALL)TopuUtilityManager.setEnabled(u,v);ConfigManager.save();rebuild();}).dimensions(x,y,152,24).build());}private void rebuild(){List<net.minecraft.client.gui.widget.ClickableWidget> rm=new ArrayList<>();for(var w:children())if(w instanceof ButtonWidget b&&b.getX()>=190)rm.add(b);rm.forEach(this::remove);TopuUtilityManager.Utility[] a=TopuUtilityManager.search(search==null?"":search.getText(),category);int st=Math.max(0,Math.min(scroll,Math.max(0,a.length-12))),n=Math.min(12,a.length-st),left=212,cw=Math.max(220,(width-left-30)/2);for(int i=0;i<n;i++){TopuUtilityManager.Utility u=a[st+i];int x=left+(i%2)*cw,y=100+(i/2)*62;boolean on=TopuUtilityManager.isEnabled(u);ButtonWidget b=ButtonWidget.builder(Text.literal((on?"● ON  ":"○ OFF ")+u.name()),z->{boolean q=!TopuUtilityManager.isEnabled(u);TopuUtilityManager.setEnabled(u,q);ConfigManager.save();z.setMessage(Text.literal((q?"● ON  ":"○ OFF ")+u.name()));}).dimensions(x,y,cw-10,44).build();addDrawableChild(b);}}private static String pretty(String s){return s.substring(0,1)+s.substring(1).toLowerCase();}@Override public boolean mouseScrolled(double x,double y,double h,double v){if(x>190){TopuUtilityManager.Utility[] a=TopuUtilityManager.search(search==null?"":search.getText(),category);int max=Math.max(0,a.length-12);scroll=Math.max(0,Math.min(max,scroll+(v<0?2:-2)));rebuild();return true;}return super.mouseScrolled(x,y,h,v);}@Override public void close(){ConfigManager.save();MinecraftClient.getInstance().setScreen(parent);}@Override public void render(DrawContext d,int mx,int my,float delta){d.fill(0,0,width,height,0xFF070A10);d.fill(0,0,width,68,0xFF0E141E);d.fill(0,68,190,height,0xFF0A1018);d.fill(190,68,192,height,0xFF263246);d.fill(22,67,166,69,0xFF6FA8FF);d.drawTextWithShadow(textRenderer,Text.literal("TOPU"),22,18,0xFFFFFFFF);d.drawTextWithShadow(textRenderer,Text.literal("HUD"),73,18,0xFF6FA8FF);d.drawText(textRenderer,Text.literal("UTILITY CONTROL"),22,43,0xFF8390A4,false);d.drawText(textRenderer,Text.literal("RIGHT SHIFT  •  50 MODULES"),width-158,45,0xFF7D8BA0,false);d.drawText(textRenderer,Text.literal("CATEGORIES"),20,76,0xFF66758A,true);String active=category==null?"ALL UTILITIES":pretty(category.name());TopuUtilityManager.Utility[] a=TopuUtilityManager.search(search==null?"":search.getText(),category);d.drawTextWithShadow(textRenderer,Text.literal(active),212,80,0xFFEAF1FB);d.drawText(textRenderer,Text.literal(a.length+" available"),width-82,82,0xFF78869A,false);super.render(d,mx,my,delta);}}
